  function renderDomainCard() { const domain = domainContext(); if (!domain.root) { els.domainCard.innerHTML = '<h3>未关联领域 Harness</h3><p>Harness 是可选增强项。当前 Work Run 会使用补充上下文、需求材料和当前代码继续；后续仍可按需挂载。</p>'; return; } const domains = (state.status.config && state.status.config.domains) || [domain]; const repos = domain.codeRepositories || []; const local = repos.filter((repo) => repo.sourceExists).map((repo) => repo.name); const linked = domains.map((item) => `<li><strong>${escapeHtml(item.name || item.id || basename(item.root))}</strong>${item.root === domain.root ? '（主）' : '（参考）'}<br><small>${escapeHtml(item.root || '')}</small><br><small>版本 ${escapeHtml(String(item.revision || 'unversioned').slice(0, 12))} · 代码入口 ${(item.codeRepositories || []).length}</small></li>`).join(''); els.domainCard.innerHTML = `<h3>主领域：${escapeHtml(domain.name || domain.id || basename(domain.root))}</h3><p class="path">${escapeHtml(domain.root)}</p><span class="badge">版本 ${escapeHtml(String(domain.revision || 'unversioned').slice(0, 12))}</span><div class="capability-group"><strong>已挂载 Harness · ${domains.length}</strong><ul>${linked}</ul></div><div class="capability-group"><strong>主领域资料</strong><p>白皮书 ${(domain.productDocuments || []).length} · 领域记忆 ${(domain.memoryDocuments || []).length} · 代码入口 ${repos.length}${local.length ? ` · 本地代码 ${local.length}` : ''}</p></div><div class="card-actions"><button data-open-configured-folder="domain" type="button">打开主领域目录</button></div>`; bindConfiguredFolderActions(els.domainCard); }
