  function renderGates() { const step = state.status.steps && state.status.steps['manual-release']; const risks = state.status.risks || { total: 0, unresolved: [] }; if (!step) { els.gatesPanel.innerHTML = '<section class="card gate">未读取到发布确认节点。</section>'; return; } const checkpoint = step.checkpoint || {}; const status = checkpoint.status || 'pending'; const files = checkpoint.reviewFiles || []; const filesReady = files.every((item) => item.optional || item.exists); const checklist = step.checklist || []; const checklistHtml = checklist.map((item) => `<label><input type="checkbox" data-release-check="${escapeHtml(item.id)}" ${status === 'approved' ? 'checked disabled' : ''} /> ${escapeHtml(item.label)}</label>`).join(''); const evidence = files.map((item) => `<span class="evidence ${item.exists ? 'ok' : 'missing'}">${escapeHtml(item.path)}</span>`).join(''); const canConfirm = state.status.deliveryValidation && state.status.deliveryValidation.status === 'ready' && risks.unresolved.length === 0 && filesReady; const actions = status === 'approved' ? '<span class="badge status-approved">已确认发布</span>' : `<input data-release-note placeholder="确认或退回说明" /><button data-release-action="approve" class="primary" type="button" ${canConfirm ? '' : 'disabled'}>人工确认发布</button><button data-release-action="reject" type="button">退回修改</button>`; els.gatesPanel.innerHTML = `<article class="card gate"><div><h3>人工发布确认</h3><small>三份交付物必须绑定当前代码指纹；当前未解决风险 ${risks.unresolved.length} 项。</small></div><div class="gate-evidence">${evidence}</div><div class="capability-group">${checklistHtml}</div><div class="gate-actions">${actions}</div></article>`; els.gatesPanel.querySelectorAll('[data-release-action]').forEach((button) => button.addEventListener('click', () => releaseAction(button.dataset.releaseAction).catch((error) => message(error.message, 'error')))); }
